 output.mkdir(parents=True,exist_ok=False);n=json.loads((native/'manifest.json').read_text());m=json.loads((metal/'manifest.json').read_text());assert n['status']=='bounded_native_preflight'and m['status']=='pass';assert len(m['frames'])==201 and m['sample_simulation_ticks']==list(range(1,202));whole=Image.new('RGB',(1280,len(SELECTED)*505));crop=Image.new('RGB',(400,len(SELECTED)*465));w=ImageDraw.Draw(whole);c=ImageDraw.Draw(crop);pairs=[]
